import { VecBase } from "./VecBase";
export class Vec3 extends VecBase {
    static ZERO = new Vec3(0, 0, 0);
    static ONE = new Vec3(1, 1, 1);
    static UNIT_X = new Vec3(1, 0, 0);
    static UNIT_Y = new Vec3(0, 1, 0);
    static UNIT_Z = new Vec3(0, 0, 1);
    static NEG_X = new Vec3(-1, 0, 0);
    static NEG_Y = new Vec3(0, -1, 0);
    static NEG_Z = new Vec3(0, 0, -1);
    x;
    y;
    z;
    constructor(x, y, z) {
        super();
        this.x = x ?? 0;
        this.y = y ?? 0;
        this.z = z ?? 0;
    }
    // Required methods
    clone() {
        return new Vec3(this.x, this.y, this.z);
    }
    add(v) {
        return new Vec3(this.x + v.x, this.y + v.y, this.z + v.z);
    }
    scale(s) {
        return new Vec3(s * this.x, s * this.y, s * this.z);
    }
    dot(v) {
        return this.x * v.x + this.y * v.y + this.z * v.z;
    }
    toString() {
        return `Vec3(${this.x.toFixed(3)}, ${this.y.toFixed(3)}, ${this.z.toFixed(3)})`;
    }
    // Additional methods
    rotateX(theta) {
        const x = this.x;
        const y = this.y * Math.cos(theta) - this.z * Math.sin(theta);
        const z = this.y * Math.sin(theta) + this.z * Math.cos(theta);
        return new Vec3(x, y, z);
    }
    rotateY(theta) {
        const x = this.x * Math.cos(theta) + this.z * Math.sin(theta);
        const y = this.y;
        const z = -this.x * Math.sin(theta) + this.z * Math.cos(theta);
        return new Vec3(x, y, z);
    }
    rotateZ(theta) {
        const x = this.x * Math.cos(theta) - this.z * Math.sin(theta);
        const y = this.x * Math.sin(theta) + this.z * Math.cos(theta);
        const z = this.z;
        return new Vec3(x, y, z);
    }
}
